create table "Store" (
	"Id" INTEGER generated by default as identity primary key not null,
	"Address" VARCHAR(255) not null
);

create table "ClothingItem" (
	"Id" INTEGER generated by default as identity primary key not null,
	"Name" VARCHAR(255) not null,
	"Type" VARCHAR(255) not null,
	"Sizes" VARCHAR(255) not null,
	"Material" VARCHAR(255),
	"Description" TEXT
);

create table "Customer" (
	"Id" INTEGER generated by default as identity primary key not null,
	"FirstName"  VARCHAR(255) not null,
	"LastName"  VARCHAR(255) not null
);

create table "Employee" (
	"Id" INTEGER generated by default as identity primary key not null,
	"FirstName"  VARCHAR(255) not null,
	"LastName"  VARCHAR(255) not null,
	"StoreId" INTEGER references "Store"("Id") not null,
	"StartedOn" DATE not null
);

create table "Order" (
	"Id" INTEGER generated by default as identity primary key not null,
	"EmployeeId" INTEGER references "Employee"("Id") not null,
	"CustomerId" INTEGER references "Customer"("Id") not null,
	"StoreId" INTEGER references "Store"("Id") not null,
	"CreatedAt" timestamp default current_timestamp not null
);

create table "OrderItem" (
	"Id" INTEGER generated by default as identity primary key not null,
	"OrderId" INTEGER references "Order"("Id") not null,
	"ClothingItemId" INTEGER references "ClothingItem"("Id") not null
);

