select o."Id", e."FirstName" as "Employee name", e."LastName" as "Employee surname",
c."FirstName" as "Customer name", c."LastName" as "Customer surname",
ci."Name" as "Product name", ci."Material", ci."Description" as "Product description",
o."CreatedAt"
	from "Order" as o
		left join "Employee" as e on (o."EmployeeId" = e."Id")
		left join "OrderItem" as i on (o."Id" = i."OrderId")
		join "ClothingItem" as ci on (i."ClothingItemId" = ci."Id")
		left join "Customer" as c on (c."Id" = o."CustomerId" )
		order by o."CreatedAt" ASC;

select * from "ClothingItem" as ci
	left join "OrderItem" as i on (i."ClothingItemId" = ci."Id")
	right join "Order" as o on (i."OrderId" = o."Id");

delete from select * from "ClothingItem" as ci
	left join "OrderItem" as i on (i."ClothingItemId" = ci."Id")
	right join "Order" as o on (i."OrderId" = o."Id")
		where("ClothingItemId" == null);

delete from select * from "Order"
	where ("CreatedAt" between ('1.1.2025' and '31.1.2026'));

update "ClothingItem" set "Description" = 'Dugacke plave linene hlace'
	where (ci."Material" = 'linen');
update "Order" set "CreatedAt" = current_timestamp
	where("CreatedAt" between ('1.1.2023' and '1.2.2023'));